
USE [olist_dwh];
GO

--=========================================================================
-- create the geography dimension table
-- i am creating the geography dimension in the gold schema.
-- geography_key will be the surrogate key generated by sql server.
-- geography_zip_code_prefix will identify each geographical location.
-- the remaining columns will provide geographical information.
--=========================================================================

IF OBJECT_ID('[gold].[dim_geography]', 'U') IS NULL
BEGIN
    CREATE TABLE [gold].[dim_geography]
    (
        geography_key INT IDENTITY(1,1) NOT NULL,
        geography_zip_code_prefix VARCHAR(10) NOT NULL,
        latitude DECIMAL(10,8) NULL,
        longitude DECIMAL(11,8) NULL,
        city NVARCHAR(255) NOT NULL,
        state NVARCHAR(255) NOT NULL,

        CONSTRAINT PK_dim_geography
            PRIMARY KEY (geography_key)
    );
END;
GO

--=========================================================================
-- create a unique index for the geography business key
-- i am ensuring that each zip code prefix can only appear once
-- in the geography dimension.
-- this prevents duplicate geographical records from being inserted.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM sys.indexes
    WHERE name = 'UX_dim_geography'
      AND object_id = OBJECT_ID('[gold].[dim_geography]')
)
BEGIN
    CREATE UNIQUE NONCLUSTERED INDEX UX_dim_geography
    ON [gold].[dim_geography] (geography_zip_code_prefix);
END;
GO

--=========================================================================
-- insert the unknown geography record
-- i am inserting an unknown geography with geography_key = -1.
-- this record will be used when a customer or seller location
-- cannot be matched during the fact table loading process.
-- identity_insert allows me to insert -1 manually.
-- the if not exists check prevents duplicate unknown records.
--=========================================================================

IF NOT EXISTS
(
    SELECT 1
    FROM [gold].[dim_geography]
    WHERE geography_key = -1
)
BEGIN
    SET IDENTITY_INSERT [gold].[dim_geography] ON;

    INSERT INTO [gold].[dim_geography]
    (
        geography_key,
        geography_zip_code_prefix,
        latitude,
        longitude,
        city,
        state
    )
    VALUES
    (
        -1,
        'Unknown',
        NULL,
        NULL,
        'Unknown',
        'Unknown'
    );

    SET IDENTITY_INSERT [gold].[dim_geography] OFF;
END;
GO
